# helpers.R — Pure-R prediction engine for LL.4 dose-response models
# No external dependencies beyond base R

# LL.4 formula: f(x) = c + (d - c) / (1 + (x / e)^b)
# b = slope, c = lower asymptote (c_min), d = upper asymptote, e = EC50
ll4_predict <- function(conc, b, c_min, d, e) {
  if (conc <= 0) return(d)
  c_min + (d - c_min) / (1 + (conc / e)^b)
}

# Vectorized version for smooth curve generation
ll4_predict_vec <- function(conc, b, c_min, d, e) {
  out <- numeric(length(conc))
  for (i in seq_along(conc)) {
    out[i] <- ll4_predict(conc[i], b, c_min, d, e)
  }
  out
}

# Extract parameters for one model x time combination
get_params <- function(params_df, model_id, time_h) {
  p <- params_df[params_df$model_id == model_id & params_df$time_h == time_h, ]
  list(
    b = p$value[p$parameter == "b"],
    c_min = p$value[p$parameter == "c"],
    d = p$value[p$parameter == "d"],
    e = p$value[p$parameter == "e"],
    rse = p$rse[1],
    df_resid = p$df_resid[1],
    n_per_curve = p$n_per_curve[1]
  )
}

# Point prediction + 95% CI + 95% PI
predict_with_intervals <- function(conc, params) {
  pred <- ll4_predict(conc, params$b, params$c_min, params$d, params$e)
  sigma <- params$rse
  t_crit <- qt(0.975, params$df_resid)
  n <- params$n_per_curve

  ci_half <- t_crit * sigma / sqrt(n)
  pi_half <- t_crit * sigma * sqrt(1 + 1 / n)

  list(
    pred = pred,
    ci_lo = pred - ci_half,
    ci_hi = pred + ci_half,
    pi_lo = pred - pi_half,
    pi_hi = pred + pi_half,
    ci_half = ci_half,
    pi_half = pi_half
  )
}

# Quality assessment: zone, color, interpretation
assess_quality <- function(conc, pred, d, c_min, variable, lang = "en") {
  # Zone classification
  if (conc == 0) {
    zone <- "control"
    color <- "#d4edda"
  } else if (conc <= 75) {
    zone <- "interpolation"
    color <- "#d4edda"
  } else if (conc <= 150) {
    zone <- "near_extrapolation"
    color <- "#fff3cd"
  } else {
    zone <- "far_extrapolation"
    color <- "#f8d7da"
  }

  # Percent change from control (d = control response)
  if (abs(d) < 1e-10) {
    pct_change <- NA_real_
  } else {
    pct_change <- ((pred - d) / abs(d)) * 100
  }

  # For decreasing variables (Q_Yield, Chl_Act_pct): reduction from control
  # For increasing variables (P4): increase from control
  is_increasing <- variable == "P4"

  if (is_increasing) {
    change_mag <- pct_change  # positive = increase
  } else {
    change_mag <- -pct_change  # positive = reduction
  }

  # Effect severity labels
  if (is.na(change_mag)) {
    severity <- if (lang == "en") "Cannot assess" else "No evaluable"
  } else if (change_mag < 5) {
    severity <- if (lang == "en") "No appreciable effect" else
      "Sin efecto apreciable"
  } else if (change_mag < 20) {
    severity <- if (lang == "en") "Mild impairment" else
      "Deterioro leve"
  } else if (change_mag < 50) {
    severity <- if (lang == "en") "Moderate impairment" else
      "Deterioro moderado"
  } else if (change_mag < 80) {
    severity <- if (lang == "en") "Severe impairment" else
      "Deterioro severo"
  } else {
    severity <- if (lang == "en") "Near-complete suppression" else
      "Casi completa"
  }

  # For P4 (increasing), relabel

  if (is_increasing && !is.na(change_mag) && change_mag >= 5) {
    if (change_mag < 20) {
      severity <- if (lang == "en") "Mild increase" else "Aumento leve"
    } else if (change_mag < 50) {
      severity <- if (lang == "en") "Moderate increase" else "Aumento moderado"
    } else if (change_mag < 80) {
      severity <- if (lang == "en") "Strong increase" else "Aumento fuerte"
    } else {
      severity <- if (lang == "en") "Dominant restructuring" else
        "Reestructuracion dominante"
    }
  }

  # Zone text
  zone_labels <- list(
    en = c(control = "Control (reference)",
           interpolation = "Interpolation (high confidence)",
           near_extrapolation = "Near extrapolation (moderate confidence)",
           far_extrapolation = "Far extrapolation (NOT recommended)"),
    es = c(control = "Control (referencia)",
           interpolation = "Interpolacion (alta confianza)",
           near_extrapolation = "Extrapolacion cercana (confianza moderada)",
           far_extrapolation = "Extrapolacion lejana (NO recomendado)")
  )

  list(
    zone = zone,
    color = color,
    pct_change = round(pct_change, 2),
    severity = severity,
    quality = zone_labels[[lang]][[zone]]
  )
}

# Parse user-entered concentrations from text
parse_concentrations <- function(text) {
  if (is.null(text) || nchar(trimws(text)) == 0) return(numeric(0))
  # Split on comma, semicolon, space, newline, tab
  vals <- unlist(strsplit(text, "[,;\\s]+", perl = TRUE))
  vals <- vals[nchar(vals) > 0]
  nums <- suppressWarnings(as.numeric(vals))
  nums <- nums[!is.na(nums)]
  nums <- nums[nums >= 0]  # drop negatives
  sort(unique(nums))
}

# Generate smooth curve data for plotting
generate_curve_data <- function(params_df, model_id, time_h, conc_range = c(0.1, 150)) {
  params <- get_params(params_df, model_id, time_h)
  if (length(params$b) == 0) return(NULL)

  concs <- seq(conc_range[1], conc_range[2], length.out = 300)
  preds <- ll4_predict_vec(concs, params$b, params$c_min, params$d, params$e)

  sigma <- params$rse
  t_crit <- qt(0.975, params$df_resid)
  n <- params$n_per_curve

  ci_half <- t_crit * sigma / sqrt(n)
  pi_half <- t_crit * sigma * sqrt(1 + 1 / n)

  data.frame(
    concentration_mg_L = concs,
    pred = preds,
    ci_lo = preds - ci_half,
    ci_hi = preds + ci_half,
    pi_lo = preds - pi_half,
    pi_hi = preds + pi_half,
    model_id = model_id,
    time_h = time_h,
    time_label = paste0(time_h, "h"),
    stringsAsFactors = FALSE
  )
}

# Check if a curve is poorly identified (low slope)
is_poorly_identified <- function(params) {
  abs(params$b) < 0.01
}
